/**
 * Makes pnpm the preselected tab in the blocks generated by
 * `@docusaurus/remark-plugin-npm2yarn`.
 *
 * That plugin always emits npm as the first `TabItem` and offers no way to set a
 * default, so without this every `npm2yarn` fence opens on npm. Rather than writing
 * the tabs out by hand in every page, this runs after it and adds
 * `defaultValue="pnpm"` to the `<Tabs>` it produced, leaving the tab order alone.
 *
 * It only touches the Tabs npm2yarn generates — matched by its `groupId` — so
 * hand-written tabs elsewhere keep their own default.
 */
const NPM2YARN_GROUP_ID = 'npm2yarn';
const DEFAULT_VALUE = 'pnpm';

function isNpm2YarnTabs(node) {
  return (
    node.type === 'mdxJsxFlowElement' &&
    node.name === 'Tabs' &&
    Array.isArray(node.attributes) &&
    node.attributes.some(
      (attr) => attr.name === 'groupId' && attr.value === NPM2YARN_GROUP_ID
    )
  );
}

function hasTab(node, value) {
  return (node.children ?? []).some(
    (child) =>
      child.type === 'mdxJsxFlowElement' &&
      child.name === 'TabItem' &&
      (child.attributes ?? []).some((attr) => attr.name === 'value' && attr.value === value)
  );
}

module.exports = function remarkNpm2YarnDefaultPnpm() {
  return (root) => {
    const visit = (node) => {
      if (!Array.isArray(node.children)) {
        return;
      }
      for (const child of node.children) {
        // only add the default when a pnpm tab actually exists, so a converters
        // list without pnpm does not end up pointing at a missing tab
        if (
          isNpm2YarnTabs(child) &&
          hasTab(child, DEFAULT_VALUE) &&
          !child.attributes.some((attr) => attr.name === 'defaultValue')
        ) {
          child.attributes.push({
            type: 'mdxJsxAttribute',
            name: 'defaultValue',
            value: DEFAULT_VALUE,
          });
        }
        visit(child);
      }
    };
    visit(root);
  };
};
